	public static String format(Temporal t) {
		StringBuilder sb = new StringBuilder(32);
		LocalDateTime local = t.local;
		if (t.kind.hasDate()) {
			int year = local.getYear();
			if (year < 0) {
				sb.append('-');
				year = -year;
			}
			if (year < 1000) {
				sb.append(year < 10 ? "000" : year < 100 ? "00" : "0");
			}
			sb.append(year).append('-');
			appendTwoDigits(sb, local.getMonthValue()).append('-');
			appendTwoDigits(sb, local.getDayOfMonth());
			if (t.kind.hasTime()) {
				sb.append('T');
			}
		}
		if (t.kind.hasTime()) {
			appendTwoDigits(sb, local.getHour()).append(':');
			appendTwoDigits(sb, local.getMinute()).append(':');
			appendTwoDigits(sb, local.getSecond());
			int nanos = local.getNano();
			if (nanos != 0) {
				String fraction = Integer.toString(nanos + 1_000_000_000).substring(1);
				int end = fraction.length();
				while (fraction.charAt(end - 1) == '0') {
					end--;
				}
				sb.append('.').append(fraction, 0, end);
			}
		}
		if (t.offset != null) {
			if (t.offset.getTotalSeconds() == 0) {
				sb.append('Z');
			} else {
				sb.append(t.offset.getId());
			}
		}
		return sb.toString();
	}

